window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cfbc743fd8e09fc7"]={"versions": [{"id": "FIG-cfbc743fd8e09fc7", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherlayout-Diagramm (logischer Blockaufbau) aus der Spezifikation des AUTOSAR NVRAM Managers (NvM). Das Diagramm visualisiert die logische Struktur und Unterteilung eines RAM-Blocks in Header-, Nutzdaten- und CRC-Bereiche innerhalb des BSW-Speicherverwaltungskontexts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei logische Segmente bilden den RAM-Block:</p>\n<ul class=\"fig-list\"><li><code>NV block Header (optional)</code> / zugeordnet zu <code>RAM block Header Field</code> (oben, grau hinterlegt)\n</li><li><code>RAM block data (permanent/temporary)</code> / zugeordnet zu <code>RAM Block Data Field</code> (Mitte, blau hinterlegt, von einer gestrichelten Außenkontur für den Anwendungsdatenbereich umfasst)\n</li><li><code>RAM block CRC (optional)</code> / zugeordnet zu <code>RAM block CRC Field</code> (unten, grau hinterlegt)\n</li></ul>\n<p class=\"fig-p\">Rechts kennzeichnen drei vertikale Maßpfeile mit horizontalen Hilfslinien die jeweiligen Feldgrenzen. Die gestrichelte Umrandung umfasst primär das Nutzdatenfeld sowie das CRC-Feld.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Anordnung verdeutlicht die logische Zusammenfassung und Reihenfolge der Felder bei Speicheroperationen (wie Lesen, Schreiben oder Prüfsummenberechnung über Nutzdaten und optionale Zusatzfelder) durch den NVRAM Manager.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert nicht das physikalische Memory-Layout oder die Bytereihenfolge im Speicher, sondern ausschließlich das logische Clustering. Da das NvM-Modul kein automatisches Alignment unterstützt, muss dieses bei Bedarf durch Konfiguration (z. B. Hinzufügen von Padding-Bytes zur Blocklänge) sichergestellt werden. Header- und CRC-Felder sind je nach Blockkonfiguration optional.</p>"}, {"id": "FIG-efa2a253d3fd7281", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherlayout-Diagramm (logischer Blockaufbau) aus der Spezifikation des AUTOSAR NVRAM Managers (NvM). Das Diagramm visualisiert die logische Struktur und Unterteilung eines RAM-Blocks in Header-, Nutzdaten- und CRC-Bereiche innerhalb des BSW-Speicherverwaltungskontexts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei logische Segmente bilden den RAM-Block:</p>\n<ul class=\"fig-list\"><li><code>NV block Header (optional)</code> / zugeordnet zu <code>RAM block Header Field</code> (oben, grau hinterlegt)\n</li><li><code>RAM block data (permanent/temporary)</code> / zugeordnet zu <code>RAM Block Data Field</code> (Mitte, blau hinterlegt, von einer gestrichelten Außenkontur für den Anwendungsdatenbereich umfasst)\n</li><li><code>RAM block CRC (optional)</code> / zugeordnet zu <code>RAM block CRC Field</code> (unten, grau hinterlegt)\n</li></ul>\n<p class=\"fig-p\">Rechts kennzeichnen drei vertikale Maßpfeile mit horizontalen Hilfslinien die jeweiligen Feldgrenzen. Die gestrichelte Umrandung umfasst primär das Nutzdatenfeld sowie das CRC-Feld.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Anordnung verdeutlicht die logische Zusammenfassung und Reihenfolge der Felder bei Speicheroperationen (wie Lesen, Schreiben oder Prüfsummenberechnung über Nutzdaten und optionale Zusatzfelder) durch den NVRAM Manager.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert nicht das physikalische Memory-Layout oder die Bytereihenfolge im Speicher, sondern ausschließlich das logische Clustering. Da das NvM-Modul kein automatisches Alignment unterstützt, muss dieses bei Bedarf durch Konfiguration (z. B. Hinzufügen von Padding-Bytes zur Blocklänge) sichergestellt werden. Header- und CRC-Felder sind je nach Blockkonfiguration optional.</p>"}, {"id": "FIG-308d155b44075cde", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherlayout-Diagramm (logischer Blockaufbau) aus der Spezifikation des AUTOSAR NVRAM Managers (NvM). Das Diagramm visualisiert die logische Struktur und Unterteilung eines RAM-Blocks in Header-, Nutzdaten- und CRC-Bereiche innerhalb des BSW-Speicherverwaltungskontexts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei logische Segmente bilden den RAM-Block:</p>\n<ul class=\"fig-list\"><li><code>NV block Header (optional)</code> / zugeordnet zu <code>RAM block Header Field</code> (oben, grau hinterlegt)\n</li><li><code>RAM block data (permanent/temporary)</code> / zugeordnet zu <code>RAM Block Data Field</code> (Mitte, blau hinterlegt, von einer gestrichelten Außenkontur für den Anwendungsdatenbereich umfasst)\n</li><li><code>RAM block CRC (optional)</code> / zugeordnet zu <code>RAM block CRC Field</code> (unten, grau hinterlegt)\n</li></ul>\n<p class=\"fig-p\">Rechts kennzeichnen drei vertikale Maßpfeile mit horizontalen Hilfslinien die jeweiligen Feldgrenzen. Die gestrichelte Umrandung umfasst primär das Nutzdatenfeld sowie das CRC-Feld.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Anordnung verdeutlicht die logische Zusammenfassung und Reihenfolge der Felder bei Speicheroperationen (wie Lesen, Schreiben oder Prüfsummenberechnung über Nutzdaten und optionale Zusatzfelder) durch den NVRAM Manager.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert nicht das physikalische Memory-Layout oder die Bytereihenfolge im Speicher, sondern ausschließlich das logische Clustering. Da das NvM-Modul kein automatisches Alignment unterstützt, muss dieses bei Bedarf durch Konfiguration (z. B. Hinzufügen von Padding-Bytes zur Blocklänge) sichergestellt werden. Header- und CRC-Felder sind je nach Blockkonfiguration optional.</p>"}, {"id": "FIG-a688aaf6ad20becf", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherlayout-Diagramm (logischer Blockaufbau) aus der Spezifikation des AUTOSAR NVRAM Managers (NvM). Das Diagramm visualisiert die logische Struktur und Unterteilung eines RAM-Blocks in Header-, Nutzdaten- und CRC-Bereiche innerhalb des BSW-Speicherverwaltungskontexts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei logische Segmente bilden den RAM-Block:</p>\n<ul class=\"fig-list\"><li><code>NV block Header (optional)</code> / zugeordnet zu <code>RAM block Header Field</code> (oben, grau hinterlegt)\n</li><li><code>RAM block data (permanent/temporary)</code> / zugeordnet zu <code>RAM Block Data Field</code> (Mitte, blau hinterlegt, von einer gestrichelten Außenkontur für den Anwendungsdatenbereich umfasst)\n</li><li><code>RAM block CRC (optional)</code> / zugeordnet zu <code>RAM block CRC Field</code> (unten, grau hinterlegt)\n</li></ul>\n<p class=\"fig-p\">Rechts kennzeichnen drei vertikale Maßpfeile mit horizontalen Hilfslinien die jeweiligen Feldgrenzen. Die gestrichelte Umrandung umfasst primär das Nutzdatenfeld sowie das CRC-Feld.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicherabbild ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Anordnung verdeutlicht die logische Zusammenfassung und Reihenfolge der Felder bei Speicheroperationen (wie Lesen, Schreiben oder Prüfsummenberechnung über Nutzdaten und optionale Zusatzfelder) durch den NVRAM Manager.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert nicht das physikalische Memory-Layout oder die Bytereihenfolge im Speicher, sondern ausschließlich das logische Clustering. Da das NvM-Modul kein automatisches Alignment unterstützt, muss dieses bei Bedarf durch Konfiguration (z. B. Hinzufügen von Padding-Bytes zur Blocklänge) sichergestellt werden. Header- und CRC-Felder sind je nach Blockkonfiguration optional.</p>"}], "trans": [{"from": "FIG-cfbc743fd8e09fc7", "to": "FIG-efa2a253d3fd7281", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-efa2a253d3fd7281", "to": "FIG-308d155b44075cde", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-308d155b44075cde", "to": "FIG-a688aaf6ad20becf", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
